// Feature 3 — Identity Registry client (browser).
// Reads/writes the deployed IdentityRegistry.sol directly through the injected EIP-1193 wallet:
//   - createIdentity / deactivateIdentity / activateIdentity send transactions (wallet confirms them)
//   - getIdentity / verifyIdentity / identityCount / identityAt are read-only eth_call queries
// Contract ABI is generated by Hardhat and copied to src/identity/abi/IdentityRegistry.json.
// Addresses come from localStorage (Settings page) or VITE_IDENTITY_REGISTRY_ADDRESS.

import type { Eip1193Provider } from '../wallet/eip1193';
import { getProvider } from '../wallet/eip1193';
import { keccak256, toHex } from 'viem';

// Hardhat-generated ABI (copied by `npm run sync-abi` from contracts/artifacts).
// Exported so future features (indexer/UI event decoding in F10/F11) reuse the exact on-chain ABI.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import abiData from './abi/IdentityRegistry.json';

export const IDENTITY_ABI = abiData.abi as readonly object[];

const ADDR_KEY = 'platform.identityRegistryAddress';

export function getRegistryAddress(): string | null {
  const fromEnv = (import.meta.env.VITE_IDENTITY_REGISTRY_ADDRESS as string | undefined) ?? '';
  const stored = typeof localStorage !== 'undefined' ? localStorage.getItem(ADDR_KEY) : null;
  const addr = (stored || fromEnv).trim();
  return /^0x[0-9a-fA-F]{40}$/.test(addr) ? addr : null;
}

export function setRegistryAddress(addr: string): void {
  if (!/^0x[0-9a-fA-F]{40}$/.test(addr.trim())) throw new Error('Invalid registry address');
  localStorage.setItem(ADDR_KEY, addr.trim());
}

async function rpc<T = unknown>(provider: Eip1193Provider, method: string, params: unknown[]): Promise<T> {
  return (await provider.request({ method, params })) as T;
}

// ---------- ABI encoding helpers (minimal hand-rolled encoder for this contract's calls) ----------
function pad(hexNo0x: string): string {
  return hexNo0x.padStart(64, '0');
}
function addrWord(addr: string): string {
  return pad(addr.toLowerCase().replace(/^0x/, ''));
}
function selector(sig: string): string {
  // keccak256(signature)[0:4] — viem hash utilities, no client needed
  return keccakSelectorCache(sig);
}
const selCache = new Map<string, string>();
function keccakSelectorCache(sig: string): string {
  let s = selCache.get(sig);
  if (!s) {
    s = keccak256(toHex(sig), 'string').slice(0, 10);
    selCache.set(sig, s);
  }
  return s;
}

function encodeCall(fn: string, args: string[]): string {
  return selector(fn) + args.map(addrWord).join('');
}

// ---------- Read operations (eth_call) ----------
export interface IdentityRecord {
  wallet: string;
  refHash: string;
  active: boolean;
  createdAt: bigint;
  updatedAt: bigint;
}

function decodeWord(hex: string, i: number): string {
  return '0x' + hex.slice(2 + i * 64, 2 + (i + 1) * 64);
}

export async function fetchIdentity(wallet: string, registry?: string | null): Promise<IdentityRecord | null> {
  const provider = getProvider();
  const addr = registry ?? getRegistryAddress();
  if (!provider || !addr) return null;
  try {
    const data = await rpc<string>(provider, 'eth_call', [{ to: addr, data: encodeCall('getIdentity(address)', [wallet]) }, 'latest']);
    return {
      wallet: '0x' + decodeWord(data, 0).slice(-40),
      refHash: decodeWord(data, 1),
      active: BigInt(decodeWord(data, 2)) !== 0n,
      createdAt: BigInt(decodeWord(data, 3)),
      updatedAt: BigInt(decodeWord(data, 4)),
    };
  } catch {
    return null; // IdentityNotFound reverts => not registered
  }
}

export async function fetchVerifyIdentity(wallet: string, registry?: string | null): Promise<{ verified: boolean; id: string } | null> {
  const provider = getProvider();
  const addr = registry ?? getRegistryAddress();
  if (!provider || !addr) return null;
  try {
    const data = await rpc<string>(provider, 'eth_call', [{ to: addr, data: encodeCall('verifyIdentity(address)', [wallet]) }, 'latest']);
    return { verified: BigInt(decodeWord(data, 0)) !== 0n, id: decodeWord(data, 1) };
  } catch {
    return null;
  }
}

export async function fetchIdOf(wallet: string, registry?: string | null): Promise<string | null> {
  const provider = getProvider();
  const addr = registry ?? getRegistryAddress();
  if (!provider || !addr) return null;
  return rpc<string>(provider, 'eth_call', [{ to: addr, data: encodeCall('idOf(address)', [wallet]) }, 'latest']);
}

export async function fetchIdentityList(registry?: string | null): Promise<string[]> {
  const provider = getProvider();
  const addr = registry ?? getRegistryAddress();
  if (!provider || !addr) return [];
  const countData = await rpc<string>(provider, 'eth_call', [{ to: addr, data: selector('identityCount()') }, 'latest']).catch(() => null);
  if (!countData) return [];
  const count = Number(BigInt(decodeWord(countData, 0)));
  const out: string[] = [];
  for (let i = 0; i < count; i++) {
    const word = await rpc<string>(provider, 'eth_call', [{ to: addr, data: selector('identityAt(uint256)') + pad(i.toString(16)) }, 'latest']);
    out.push('0x' + word.slice(-40));
  }
  return out;
}

// ---------- Write operations (wallet transactions) ----------
export type WriteFn = 'createIdentity(address,bytes32)' | 'deactivateIdentity(address)' | 'activateIdentity(address)';

export function encodeWrite(fn: WriteFn, args: string[]): string {
  if (fn === 'createIdentity(address,bytes32)') {
    return selector(fn) + addrWord(args[0]) + pad(args[1].replace(/^0x/, ''));
  }
  return encodeCall(fn, args);
}

export async function sendRegistryTx(fn: WriteFn, args: string[]): Promise<string> {
  const provider = getProvider();
  const addr = getRegistryAddress();
  if (!provider) throw new Error('No browser wallet detected.');
  if (!addr) throw new Error('Identity Registry address not configured (see Settings).');
  const accounts = await rpc<string[]>(provider, 'eth_accounts');
  if (!accounts.length) throw new Error('Wallet not connected.');
  const txHash = await rpc<string>(provider, 'eth_sendTransaction', [
    { from: accounts[0], to: addr, data: encodeWrite(fn, args) },
  ]);
  // Wait for inclusion so the UI can refresh against confirmed state.
  for (let attempt = 0; attempt < 60; attempt++) {
    const receipt = await rpc<{ status?: string } | null>(provider, 'eth_getTransactionReceipt', [txHash]);
    if (receipt) {
      if (receipt.status && BigInt(receipt.status) === 0n) throw new Error('Transaction reverted on-chain (check authorization/inputs).');
      return txHash;
    }
    await new Promise((r) => setTimeout(r, 1000));
  }
  throw new Error('Timed out waiting for transaction confirmation.');
}
